class InlineKeyboardButton:
    def __init__(self, data: dict):
        self.data = data

    @staticmethod
    def create(text: str,
               url: str = None,
               callback_data: str = None,
               switch_inline_query: str = None,
               switch_inline_query_current_chat: str = None):
        """
        http://core.telegram.org/bots/api#inlinekeyboardbutton
        :param text: Label text on the button
        :param url: Optional. HTTP url
        :param callback_data: Optional. Data to be sent in a callback query to the bot when button is pressed
        :param switch_inline_query: Optional. Enable switching to inline mode with a specified query
        :param switch_inline_query_current_chat: Optional. Enable switching to inline mode on the same chat lazily
        :return: inline keyboard button instance with all possible parameters
        """
        switch_inline_query_key = "switch_inline_query_current_chat" if switch_inline_query_current_chat is not None else "switch_inline_query"
        return InlineKeyboardButton({
            "text": text,
            "url": url,
            "callback_data": callback_data,
            switch_inline_query_key: switch_inline_query or switch_inline_query_current_chat
        })

    @staticmethod
    def switch_inline_query(text: str, query: str = "", current_chat: bool = True):
        switch_inline_query_key = "switch_inline_query_current_chat" if current_chat else "switch_inline_query"
        return InlineKeyboardButton({
            "text": text,
            switch_inline_query_key: query
        })

